      { ids: [12], text: '« Le notaire n’a pas bougé à 19 h 30 comme à 20 h. Il a des racines, celui-là. »' },
      { ids: [13], text: '« Le notaire a changé de pièce entre 20 h et 20 h 30. On aurait dit une limace pressée. »' },
      { ids: [14], text: '« Le docteur a changé de pièce entre 20 h 30 et 21 h, sa sacoche sous le bras. »' },
      { ids: [15], text: '« Julie n’a jamais mis les pieds dans le hall de la soirée. Ses fourneaux ne la lâchent pas. »' },
      { ids: [16], text: '« Je suis passé par la cave dans la soirée, chercher du terreau. »' },
      { ids: [17], text: '« Quand l’horloge a sonné sept coups, le docteur était à la cave. Il comptait les bouteilles, à mon avis. »' },
      { ids: [18], text: '« Quand l’horloge a sonné neuf coups, le docteur et le notaire étaient ensemble. Deux bavards dans la même casserole. »' },
      { ids: [19], text: '« À 19 h, le docteur n’était pas avec Basile. Ces deux-là ne mangent pas à la même table. »' },
      { ids: [20], text: '« Le notaire a changé de pièce entre 19 h et 19 h 30. Il a toujours faim au mauvais moment. »' }
